import { test, expect } from '@playwright/test';
import { ready } from './adapter.js';
import { mockAiResponse } from '../fixtures/mock-ai.mjs';
test('comparison runs blind, resumes locally and exports a credential-free report', async ({ page, context }) => {
  test.skip(Boolean(process.env.FRAGMENT_KIT_CONTRACT_CONFIG), 'Reference demo evaluation');
  let calls = 0;
  const models = ['good','bad'].map(name => ({ref:`openai:${name}`,name,capabilities:['generate','decide'],destination:'Mock provider',pinned:true,prices:{input:0,output:0}}));
  await context.route('**/demo/config.js', async route => { const response = await route.fetch(); await route.fulfill({response,body:(await response.text()).replace('models: [',`models: [${models.map(JSON.stringify).join(',')},`)}); });
  await context.route('https://api.openai.com/v1/chat/completions', async route => { calls++; const body = route.request().postDataJSON(), response = mockAiResponse(body,{broken:body.model==='bad'}); await route.fulfill({contentType:response.headers.get('Content-Type'),body:await response.text()}); });
  await ready(page); await page.locator('.fk-more').click(); await page.getByRole('button',{name:'AI settings',exact:true}).click();
  const settings = page.locator('#ai-settings'); await settings.getByLabel('Provider',{exact:true}).selectOption('openai'); await settings.getByLabel('API key',{exact:true}).fill('eval-probe-key'); await settings.getByRole('button',{name:'Connect key',exact:true}).click(); await settings.getByRole('button',{name:'Close',exact:true}).click();
  await page.getByRole('button',{name:'Compare models',exact:true}).click(); const compare=page.locator('#ai-compare');
  await compare.getByLabel('good → Mock provider',{exact:true}).check(); await compare.getByLabel('bad → Mock provider',{exact:true}).check(); await compare.getByLabel('Allow comparison requests').check(); await compare.getByRole('button',{name:'Run comparison',exact:true}).click();
  await expect(compare.getByRole('status')).toContainText('Comparison complete'); expect(calls).toBe(4);
  await expect(compare.locator('table')).toContainText('Model A'); await expect(compare.locator('table')).not.toContainText('openai:good');
  await compare.getByRole('button',{name:'Reveal model names'}).click(); await expect(compare.locator('table')).toContainText('openai:good');
  await compare.getByRole('button',{name:'Run comparison',exact:true}).click(); await expect(compare.getByRole('status')).toContainText('Comparison complete'); expect(calls).toBe(4);
  const downloadEvent = page.waitForEvent('download'); await compare.getByRole('button',{name:'Export report'}).click(); const download = await downloadEvent; expect(download.suggestedFilename()).toBe('ai-evaluation.json');
  await compare.getByLabel('My comparison request').fill('uppercase');
  await compare.getByRole('button',{name:'Compare my request',exact:true}).click();
  await expect(compare.getByRole('status')).toContainText('Blind proposals ready');
  await compare.locator('button[data-ai-save-case]:enabled').first().click();
  await expect(compare.getByRole('status')).toContainText('Case saved on this device');
  const saved=await page.evaluate(()=>JSON.parse(localStorage.getItem('fragment-notes:ai:cases')));
  expect(saved.cases).toHaveLength(1);expect(saved.cases[0].private).toBe(true);
  await compare.getByLabel('Include my saved cases',{exact:true}).check();
  await expect(compare.getByText(/6 calls/)).toBeVisible();
  await compare.getByRole('button',{name:'Remove saved case',exact:true}).click();
  expect(await page.evaluate(()=>localStorage.getItem('fragment-notes:ai:cases'))).toBe(null);
});
